type nodeWhere[Q sqlite.Filterable] struct {
	cols                  nodeColumns
	ID                    sqlite.WhereMod[Q, string]
	Name                  sqlite.WhereMod[Q, string]
	ListenURL             sqlite.WhereMod[Q, string]
	CertFingerprint       sqlite.WhereMod[Q, string]
	SharedSecretEncrypted sqlite.WhereMod[Q, string]
	Enabled               sqlite.WhereMod[Q, bool]
	LastSeenAt            sqlite.WhereNullMod[Q, time.Time]
	CreatedAt             sqlite.WhereMod[Q, time.Time]
	UpdatedAt             sqlite.WhereMod[Q, time.Time]
	R                     nodeWhereR[Q]
}

func (nodeWhere[Q]) AliasedAs(alias string) nodeWhere[Q] {
	return buildNodeWhere[Q](buildNodeColumns(alias))
}

func buildNodeWhere[Q sqlite.Filterable](cols nodeColumns) nodeWhere[Q] {
	return nodeWhere[Q]{
		cols:                  cols,
		ID:                    sqlite.Where[Q, string](cols.ID.Expression),
		Name:                  sqlite.Where[Q, string](cols.Name.Expression),
		ListenURL:             sqlite.Where[Q, string](cols.ListenURL.Expression),
		CertFingerprint:       sqlite.Where[Q, string](cols.CertFingerprint.Expression),
		SharedSecretEncrypted: sqlite.Where[Q, string](cols.SharedSecretEncrypted.Expression),
		Enabled:               sqlite.Where[Q, bool](cols.Enabled.Expression),
		LastSeenAt:            sqlite.WhereNull[Q, time.Time](cols.LastSeenAt.Expression),
		CreatedAt:             sqlite.Where[Q, time.Time](cols.CreatedAt.Expression),
		UpdatedAt:             sqlite.Where[Q, time.Time](cols.UpdatedAt.Expression),
		R:                     nodeWhereR[Q]{cols: cols},
	}
}

// nodeWhereR holds the relationship-based filters of
// nodeWhere under the R namespace — mirroring the model's
// R struct — so they cannot collide with column-based filter fields.
type nodeWhereR[Q sqlite.Filterable] struct {
	cols nodeColumns
}

// HasAlertRules filters parents that have a matching AlertRules using a
// correlated EXISTS subquery (semi-join). Unlike an INNER JOIN it does not
// multiply parent rows, so no DISTINCT is needed. The optional filters are
// applied to the subquery (i.e. to AlertRules).
func (w nodeWhereR[Q]) HasAlertRules(filters ...bob.Mod[*dialect.SelectQuery]) mods.Where[Q] {
	q := sqlite.Select(
		sm.Columns(sqlite.Raw("1")),
		sm.From(AlertRules.NameExpr()),
		sm.Where(AlertRules.Columns.NodeID.EQ(w.cols.ID)),
	)
	q.Apply(filters...)
	return mods.Where[Q]{E: sqlite.Exists(q)}
}

