// NULL-tolerant scan buffer for nodeScanMapperNullable:
// on a LEFT JOIN miss every column comes back NULL, so each field uses the
// nullable version of the column type even when the column itself is NOT NULL.
type nodePreloadBuf struct {
	ID                    null.Val[string]
	Name                  null.Val[string]
	ListenURL             null.Val[string]
	CertFingerprint       null.Val[string]
	SharedSecretEncrypted null.Val[string]
	Enabled               null.Val[bool]
	LastSeenAt            null.Val[time.Time]
	CreatedAt             null.Val[time.Time]
	UpdatedAt             null.Val[time.Time]
}

// nodeScanMapperNullable maps the preloaded node
// columns (prefixed with the runtime join alias) without reflection, while
// keeping the LEFT JOIN semantics of the reflection-based mapper: a row whose
// prefixed columns are all NULL yields nil (no child), and NULL values never
// error, they just leave the zero value in the field.
func nodeScanMapperNullable(prefix string) scan.Mapper[*Node] {
	return func(ctx context.Context, cols []string) (scan.BeforeFunc, func(any) (*Node, error)) {
		// resolve the column names once per query, not per row
		type target struct {
			idx int
			dst func(b *nodePreloadBuf) any
		}
		targets := make([]target, 0, 9)
		for i, col := range cols {
			name, ok := strings.CutPrefix(col, prefix)
			if !ok {
				continue
			}
			switch name {
			case "id":
				targets = append(targets, target{i, func(b *nodePreloadBuf) any { return &b.ID }})
			case "name":
				targets = append(targets, target{i, func(b *nodePreloadBuf) any { return &b.Name }})
			case "listen_url":
				targets = append(targets, target{i, func(b *nodePreloadBuf) any { return &b.ListenURL }})
			case "cert_fingerprint":
				targets = append(targets, target{i, func(b *nodePreloadBuf) any { return &b.CertFingerprint }})
			case "shared_secret_encrypted":
				targets = append(targets, target{i, func(b *nodePreloadBuf) any { return &b.SharedSecretEncrypted }})
			case "enabled":
				targets = append(targets, target{i, func(b *nodePreloadBuf) any { return &b.Enabled }})
			case "last_seen_at":
				targets = append(targets, target{i, func(b *nodePreloadBuf) any { return &b.LastSeenAt }})
			case "created_at":
				targets = append(targets, target{i, func(b *nodePreloadBuf) any { return &b.CreatedAt }})
			case "updated_at":
				targets = append(targets, target{i, func(b *nodePreloadBuf) any { return &b.UpdatedAt }})
			}
		}

		// One scratch buffer reused for every row: before -> scan -> after runs
		// synchronously per row, the scheduled columns are fully overwritten each
		// row, and unselected columns stay zero, so a single buffer preserves the
		// per-row NULL semantics without allocating a buffer per parent row. The
		// returned child (o below) is always freshly allocated, so buf never
		// escapes past the after func.
		buf := new(nodePreloadBuf)
		return func(row *scan.Row) (any, error) {
				for _, t := range targets {
					row.ScheduleScanByIndex(t.idx, t.dst(buf))
				}
				return buf, nil
			}, func(link any) (*Node, error) {
				buf := link.(*nodePreloadBuf)

				// Same rule as the reflection mapper's row validator: the child
				// exists only if at least one of its columns is not NULL. Columns
				// not selected by the query are never scanned and stay invalid,
				// so this check also matches when only a subset is selected.
				if !(buf.ID.IsValue()) &&
					!(buf.Name.IsValue()) &&
					!(buf.ListenURL.IsValue()) &&
					!(buf.CertFingerprint.IsValue()) &&
					!(buf.SharedSecretEncrypted.IsValue()) &&
					!(buf.Enabled.IsValue()) &&
					!(buf.LastSeenAt.IsValue()) &&
					!(buf.CreatedAt.IsValue()) &&
					!(buf.UpdatedAt.IsValue()) {
					return nil, nil
				}

				o := new(Node)
				if buf.ID.IsValue() {
					o.ID = buf.ID.MustGet()
				}
				if buf.Name.IsValue() {
					o.Name = buf.Name.MustGet()
				}
				if buf.ListenURL.IsValue() {
					o.ListenURL = buf.ListenURL.MustGet()
				}
				if buf.CertFingerprint.IsValue() {
					o.CertFingerprint = buf.CertFingerprint.MustGet()
				}
				if buf.SharedSecretEncrypted.IsValue() {
					o.SharedSecretEncrypted = buf.SharedSecretEncrypted.MustGet()
				}
				if buf.Enabled.IsValue() {
					o.Enabled = buf.Enabled.MustGet()
				}
				o.LastSeenAt = buf.LastSeenAt
				if buf.CreatedAt.IsValue() {
					o.CreatedAt = buf.CreatedAt.MustGet()
				}
				if buf.UpdatedAt.IsValue() {
					o.UpdatedAt = buf.UpdatedAt.MustGet()
				}
				return o, nil
			}
	}
}

func (o *Node) Preload(name string, retrieved any) error {
	if o == nil {
		return nil
	}

	switch name {
	case "AlertRules":
		rels, ok := retrieved.(AlertRuleSlice)
		if !ok {
			return fmt.Errorf("node cannot load %T as %q", retrieved, name)
		}

		o.R.AlertRules = rels
		o.R.Loaded.AlertRules = true

		for _, rel := range rels {
			if rel != nil {
				rel.R.Node = o
				rel.R.Loaded.Node = true
			}
		}
		return nil
	case "GameServers":
		rels, ok := retrieved.(GameServerSlice)
		if !ok {
			return fmt.Errorf("node cannot load %T as %q", retrieved, name)
		}

		o.R.GameServers = rels
		o.R.Loaded.GameServers = true

		for _, rel := range rels {
			if rel != nil {
				rel.R.Node = o
				rel.R.Loaded.Node = true
			}
		}
		return nil
	case "GameServerBackups":
		rels, ok := retrieved.(GameServerBackupSlice)
		if !ok {
			return fmt.Errorf("node cannot load %T as %q", retrieved, name)
		}

		o.R.GameServerBackups = rels
		o.R.Loaded.GameServerBackups = true

		for _, rel := range rels {
			if rel != nil {
				rel.R.Node = o
				rel.R.Loaded.Node = true
			}
		}
		return nil
	case "Ips":
		rels, ok := retrieved.(IPSlice)
		if !ok {
			return fmt.Errorf("node cannot load %T as %q", retrieved, name)
		}

		o.R.Ips = rels
		o.R.Loaded.Ips = true

		for _, rel := range rels {
			if rel != nil {
				rel.R.Node = o
				rel.R.Loaded.Node = true
			}
		}
		return nil
	case "NodeMetricsHistories":
		rels, ok := retrieved.(NodeMetricsHistorySlice)
		if !ok {
			return fmt.Errorf("node cannot load %T as %q", retrieved, name)
		}

		o.R.NodeMetricsHistories = rels
		o.R.Loaded.NodeMetricsHistories = true

		for _, rel := range rels {
			if rel != nil {
				rel.R.Node = o
				rel.R.Loaded.Node = true
			}
		}
		return nil
	case "SystemUpdateJobs":
		rels, ok := retrieved.(SystemUpdateJobSlice)
		if !ok {
			return fmt.Errorf("node cannot load %T as %q", retrieved, name)
		}

		o.R.SystemUpdateJobs = rels
		o.R.Loaded.SystemUpdateJobs = true

		for _, rel := range rels {
			if rel != nil {
				rel.R.Node = o
				rel.R.Loaded.Node = true
			}
		}
		return nil
	default:
		return fmt.Errorf("node has no relationship %q", name)
	}
}

