type nodeThenLoader[Q orm.Loadable] struct {
	AlertRules           func(...bob.Mod[*dialect.SelectQuery]) orm.Loader[Q]
	GameServers          func(...bob.Mod[*dialect.SelectQuery]) orm.Loader[Q]
	GameServerBackups    func(...bob.Mod[*dialect.SelectQuery]) orm.Loader[Q]
	Ips                  func(...bob.Mod[*dialect.SelectQuery]) orm.Loader[Q]
	NodeMetricsHistories func(...bob.Mod[*dialect.SelectQuery]) orm.Loader[Q]
	SystemUpdateJobs     func(...bob.Mod[*dialect.SelectQuery]) orm.Loader[Q]
}

func buildNodeThenLoader[Q orm.Loadable]() nodeThenLoader[Q] {
	type AlertRulesLoadInterface interface {
		LoadAlertRules(context.Context, bob.Executor, ...bob.Mod[*dialect.SelectQuery]) error
	}
	type GameServersLoadInterface interface {
		LoadGameServers(context.Context, bob.Executor, ...bob.Mod[*dialect.SelectQuery]) error
	}
	type GameServerBackupsLoadInterface interface {
		LoadGameServerBackups(context.Context, bob.Executor, ...bob.Mod[*dialect.SelectQuery]) error
	}
	type IpsLoadInterface interface {
		LoadIps(context.Context, bob.Executor, ...bob.Mod[*dialect.SelectQuery]) error
	}
	type NodeMetricsHistoriesLoadInterface interface {
		LoadNodeMetricsHistories(context.Context, bob.Executor, ...bob.Mod[*dialect.SelectQuery]) error
	}
	type SystemUpdateJobsLoadInterface interface {
		LoadSystemUpdateJobs(context.Context, bob.Executor, ...bob.Mod[*dialect.SelectQuery]) error
	}

	return nodeThenLoader[Q]{
		AlertRules: thenLoadBuilder[Q](
			"AlertRules",
			func(ctx context.Context, exec bob.Executor, retrieved AlertRulesLoadInterface, mods ...bob.Mod[*dialect.SelectQuery]) error {
				return retrieved.LoadAlertRules(ctx, exec, mods...)
			},
		),
		GameServers: thenLoadBuilder[Q](
			"GameServers",
			func(ctx context.Context, exec bob.Executor, retrieved GameServersLoadInterface, mods ...bob.Mod[*dialect.SelectQuery]) error {
				return retrieved.LoadGameServers(ctx, exec, mods...)
			},
		),
		GameServerBackups: thenLoadBuilder[Q](
			"GameServerBackups",
			func(ctx context.Context, exec bob.Executor, retrieved GameServerBackupsLoadInterface, mods ...bob.Mod[*dialect.SelectQuery]) error {
				return retrieved.LoadGameServerBackups(ctx, exec, mods...)
			},
		),
		Ips: thenLoadBuilder[Q](
			"Ips",
			func(ctx context.Context, exec bob.Executor, retrieved IpsLoadInterface, mods ...bob.Mod[*dialect.SelectQuery]) error {
				return retrieved.LoadIps(ctx, exec, mods...)
			},
		),
		NodeMetricsHistories: thenLoadBuilder[Q](
			"NodeMetricsHistories",
			func(ctx context.Context, exec bob.Executor, retrieved NodeMetricsHistoriesLoadInterface, mods ...bob.Mod[*dialect.SelectQuery]) error {
				return retrieved.LoadNodeMetricsHistories(ctx, exec, mods...)
			},
		),
		SystemUpdateJobs: thenLoadBuilder[Q](
			"SystemUpdateJobs",
			func(ctx context.Context, exec bob.Executor, retrieved SystemUpdateJobsLoadInterface, mods ...bob.Mod[*dialect.SelectQuery]) error {
				return retrieved.LoadSystemUpdateJobs(ctx, exec, mods...)
			},
		),
	}
}

// LoadAlertRules loads the node's AlertRules into the .R struct
func (o *Node) LoadAlertRules(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if o == nil {
		return nil
	}

	// Reset the relationship
	o.R.AlertRules = nil
	o.R.Loaded.AlertRules = false

	related, err := o.AlertRules(mods...).All(ctx, exec)
	if err != nil {
		return err
	}

	for _, rel := range related {
		rel.R.Node = o
		rel.R.Loaded.Node = true
	}

	o.R.AlertRules = related
	o.R.Loaded.AlertRules = true
	return nil
}

// LoadAlertRules loads the node's AlertRules into the .R struct
func (os NodeSlice) LoadAlertRules(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if len(os) == 0 {
		return nil
	}

	alertRules, err := os.AlertRules(mods...).All(ctx, exec)
	if err != nil {
		return err
	}

	for _, o := range os {
		if o == nil {
			continue
		}

		o.R.AlertRules = nil
		o.R.Loaded.AlertRules = true
	}
	// O(N+M) stitch via a map keyed by the join column (key -> []parent; was O(N*M)).
	nodeByKey := make(map[string][]*Node, len(os))
	for _, o := range os {
		if o == nil {
			continue
		}

		nodeByKey[o.ID] = append(nodeByKey[o.ID], o)
	}

	for _, rel := range alertRules {

		if !rel.NodeID.IsValue() {
			continue
		}

		owners, ok := nodeByKey[rel.NodeID.MustGet()]
		if !ok {
			continue
		}

		for _, o := range owners {

			rel.R.Node = o
			rel.R.Loaded.Node = true

			o.R.AlertRules = append(o.R.AlertRules, rel)

		}
	}

	return nil
}

