type nodeCountThenLoader[Q orm.Loadable] struct {
	AlertRules           func(...bob.Mod[*dialect.SelectQuery]) orm.Loader[Q]
	GameServers          func(...bob.Mod[*dialect.SelectQuery]) orm.Loader[Q]
	GameServerBackups    func(...bob.Mod[*dialect.SelectQuery]) orm.Loader[Q]
	Ips                  func(...bob.Mod[*dialect.SelectQuery]) orm.Loader[Q]
	NodeMetricsHistories func(...bob.Mod[*dialect.SelectQuery]) orm.Loader[Q]
	SystemUpdateJobs     func(...bob.Mod[*dialect.SelectQuery]) orm.Loader[Q]
}

func buildNodeCountThenLoader[Q orm.Loadable]() nodeCountThenLoader[Q] {
	type AlertRulesCountInterface interface {
		LoadCountAlertRules(context.Context, bob.Executor, ...bob.Mod[*dialect.SelectQuery]) error
	}
	type GameServersCountInterface interface {
		LoadCountGameServers(context.Context, bob.Executor, ...bob.Mod[*dialect.SelectQuery]) error
	}
	type GameServerBackupsCountInterface interface {
		LoadCountGameServerBackups(context.Context, bob.Executor, ...bob.Mod[*dialect.SelectQuery]) error
	}
	type IpsCountInterface interface {
		LoadCountIps(context.Context, bob.Executor, ...bob.Mod[*dialect.SelectQuery]) error
	}
	type NodeMetricsHistoriesCountInterface interface {
		LoadCountNodeMetricsHistories(context.Context, bob.Executor, ...bob.Mod[*dialect.SelectQuery]) error
	}
	type SystemUpdateJobsCountInterface interface {
		LoadCountSystemUpdateJobs(context.Context, bob.Executor, ...bob.Mod[*dialect.SelectQuery]) error
	}

	return nodeCountThenLoader[Q]{
		AlertRules: countThenLoadBuilder[Q](
			"AlertRules",
			func(ctx context.Context, exec bob.Executor, retrieved AlertRulesCountInterface, mods ...bob.Mod[*dialect.SelectQuery]) error {
				return retrieved.LoadCountAlertRules(ctx, exec, mods...)
			},
		),
		GameServers: countThenLoadBuilder[Q](
			"GameServers",
			func(ctx context.Context, exec bob.Executor, retrieved GameServersCountInterface, mods ...bob.Mod[*dialect.SelectQuery]) error {
				return retrieved.LoadCountGameServers(ctx, exec, mods...)
			},
		),
		GameServerBackups: countThenLoadBuilder[Q](
			"GameServerBackups",
			func(ctx context.Context, exec bob.Executor, retrieved GameServerBackupsCountInterface, mods ...bob.Mod[*dialect.SelectQuery]) error {
				return retrieved.LoadCountGameServerBackups(ctx, exec, mods...)
			},
		),
		Ips: countThenLoadBuilder[Q](
			"Ips",
			func(ctx context.Context, exec bob.Executor, retrieved IpsCountInterface, mods ...bob.Mod[*dialect.SelectQuery]) error {
				return retrieved.LoadCountIps(ctx, exec, mods...)
			},
		),
		NodeMetricsHistories: countThenLoadBuilder[Q](
			"NodeMetricsHistories",
			func(ctx context.Context, exec bob.Executor, retrieved NodeMetricsHistoriesCountInterface, mods ...bob.Mod[*dialect.SelectQuery]) error {
				return retrieved.LoadCountNodeMetricsHistories(ctx, exec, mods...)
			},
		),
		SystemUpdateJobs: countThenLoadBuilder[Q](
			"SystemUpdateJobs",
			func(ctx context.Context, exec bob.Executor, retrieved SystemUpdateJobsCountInterface, mods ...bob.Mod[*dialect.SelectQuery]) error {
				return retrieved.LoadCountSystemUpdateJobs(ctx, exec, mods...)
			},
		),
	}
}

// LoadCountAlertRules loads the count of AlertRules into the C struct
func (o *Node) LoadCountAlertRules(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if o == nil {
		return nil
	}

	count, err := o.AlertRules(mods...).Count(ctx, exec)
	if err != nil {
		return err
	}

	o.C.AlertRules = &count
	return nil
}

// LoadCountAlertRules loads the count of AlertRules for a slice in a single batch query
func (os NodeSlice) LoadCountAlertRules(ctx context.Context, exec bob.Executor, mods ...bob.Mod[*dialect.SelectQuery]) error {
	if len(os) == 0 {
		return nil
	}

	// Build the IN arg expression from parent PKs
	PKArgSlice := make([]bob.Expression, 0, len(os))
	for _, o := range os {
		if o == nil {
			continue
		}
		PKArgSlice = append(PKArgSlice, sqlite.Arg(o.ID))
	}
	PKArgExpr := sqlite.Group(PKArgSlice...)

	// countResult holds one scanned row from the batch count query.
	// FK columns are aliased to the parent PK column names for direct map lookup.
	type countResult struct {
		ID    string
		Count int64
	}

	batchMods := []bob.Mod[*dialect.SelectQuery]{
		// SELECT fk AS parent_pk, count(*)
		sm.Columns(
			AlertRules.Columns.NodeID.As("id"),
			sqlite.Raw("count(*) as count"),
		),
		// Single-hop: FROM related table directly
		sm.From(AlertRules.NameAsExpr()),

		// WHERE fk IN (parent PKs) — psql single-column FK uses `= ANY(array)` (see PKArgExpr above)
		sm.Where(AlertRules.Columns.NodeID.OP("IN", PKArgExpr)),
		// GROUP BY fk columns
		sm.GroupBy(AlertRules.Columns.NodeID),
	}
	batchMods = append(batchMods, mods...)

	results, err := bob.All(ctx, exec,
		sqlite.Select(batchMods...),
		scan.StructMapper[countResult](),
	)
	if err != nil {
		return err
	}

	// Single-column FK: direct map lookup
	countMap := make(map[string]int64, len(results))
	for _, r := range results {
		countMap[r.ID] = r.Count
	}
	for _, o := range os {
		if o == nil {
			continue
		}
		count := countMap[o.ID]
		o.C.AlertRules = &count
	}

	return nil
}

