type nodeJoins[Q dialect.Joinable] struct {
	typ                  string
	AlertRules           modAs[Q, alertRuleColumns]
	GameServers          modAs[Q, gameServerColumns]
	GameServerBackups    modAs[Q, gameServerBackupColumns]
	Ips                  modAs[Q, ipColumns]
	NodeMetricsHistories modAs[Q, nodeMetricsHistoryColumns]
	SystemUpdateJobs     modAs[Q, systemUpdateJobColumns]
}

func (j nodeJoins[Q]) aliasedAs(alias string) nodeJoins[Q] {
	return buildNodeJoins[Q](buildNodeColumns(alias), j.typ)
}

func buildNodeJoins[Q dialect.Joinable](cols nodeColumns, typ string) nodeJoins[Q] {
	return nodeJoins[Q]{
		typ: typ,
		AlertRules: modAs[Q, alertRuleColumns]{
			c: AlertRules.Columns,
			f: func(to alertRuleColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, AlertRules.NameExpr().As(to.Alias())).On(
						to.NodeID.EQ(cols.ID),
					))
				}

				return mods
			},
		},
		GameServers: modAs[Q, gameServerColumns]{
			c: GameServers.Columns,
			f: func(to gameServerColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, GameServers.NameExpr().As(to.Alias())).On(
						to.NodeID.EQ(cols.ID),
					))
				}

				return mods
			},
		},
		GameServerBackups: modAs[Q, gameServerBackupColumns]{
			c: GameServerBackups.Columns,
			f: func(to gameServerBackupColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, GameServerBackups.NameExpr().As(to.Alias())).On(
						to.NodeID.EQ(cols.ID),
					))
				}

				return mods
			},
		},
		Ips: modAs[Q, ipColumns]{
			c: Ips.Columns,
			f: func(to ipColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, Ips.NameExpr().As(to.Alias())).On(
						to.NodeID.EQ(cols.ID),
					))
				}

				return mods
			},
		},
		NodeMetricsHistories: modAs[Q, nodeMetricsHistoryColumns]{
			c: NodeMetricsHistories.Columns,
			f: func(to nodeMetricsHistoryColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, NodeMetricsHistories.NameExpr().As(to.Alias())).On(
						to.NodeID.EQ(cols.ID),
					))
				}

				return mods
			},
		},
		SystemUpdateJobs: modAs[Q, systemUpdateJobColumns]{
			c: SystemUpdateJobs.Columns,
			f: func(to systemUpdateJobColumns) bob.Mod[Q] {
				mods := make(mods.QueryMods[Q], 0, 1)

				{
					mods = append(mods, dialect.Join[Q](typ, SystemUpdateJobs.NameExpr().As(to.Alias())).On(
						to.NodeID.EQ(cols.ID),
					))
				}

				return mods
			},
		},
	}
}
